"""Small shared checkers for closed-loop UI actions (batch 4.1.1).

These helpers are intentionally narrow:

- :func:`screen_changed` is the fallback for actions that have **no dedicated
  template** (destroy-list steps, cooking animation skip, exercise roster
  refresh). It proves the click produced a visible change instead of replacing
  a fixed ``sleep`` with no verification.
- :func:`confirm_dialog_visible` is shared by build/canteen popup handling.

Semantic checkers (``SubstateSpec``, tab checkers, page checkers) remain the
first choice; this module only fills the "no anchor" gap.
"""

from __future__ import annotations

from typing import TYPE_CHECKING

import numpy as np

from autowsgr.image_resources import Templates
from autowsgr.vision import ImageChecker


if TYPE_CHECKING:
    from collections.abc import Callable

_SAMPLE_STEP = 8
"""Sample every 8th pixel, matching ``ui.utils.navigation._frame_delta``."""


def frame_delta(previous: np.ndarray, current: np.ndarray) -> float:
    """Return the sampled mean absolute difference between two frames."""
    if previous.shape != current.shape:
        return float('inf')
    a = previous[::_SAMPLE_STEP, ::_SAMPLE_STEP]
    b = current[::_SAMPLE_STEP, ::_SAMPLE_STEP]
    diff = np.abs(a.astype(np.int16) - b.astype(np.int16))
    return float(diff.mean())


def screen_changed(
    reference: np.ndarray,
    *,
    min_diff: float = 2.0,
) -> Callable[[np.ndarray], bool]:
    """Return a checker that is true once the screen differs from *reference*.

    Use only when the action has no semantic target to verify. A timeout must
    be treated as "clicked once, effect unverified" (log a warning) rather than
    as proof that the action succeeded.
    """

    def checker(screen: np.ndarray) -> bool:
        return frame_delta(reference, screen) > min_diff

    return checker


def confirm_dialog_visible(screen: np.ndarray) -> bool:
    """True when any known confirmation dialog button is on screen."""
    return ImageChecker.find_any(screen, Templates.Confirm.all()) is not None


__all__ = ['confirm_dialog_visible', 'frame_delta', 'screen_changed']
